    overflow: hidden;
}

.deals-banner::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: radial-gradient(circle at center, rgba(192, 160, 128, 0.1) 0%, transparent 70%);
}

.tag {
    display: inline-block;
    color: var(--accent-color);
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 2px;
    margin-bottom: 1rem;
    font-weight: 700;
}

.deals-content h2 {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.deals-content p {
    color: var(--text-secondary);
    margin-bottom: 2rem;
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

/* Editorial Section */
.editorial-section {
    padding: 6rem 0;
}

.editorial-grid {
    display: grid;
    grid-template-columns: 1fr 1.2fr;
    gap: 4rem;
