    font-size: 1.1rem;
}

.editorial-image {
    aspect-ratio: 4/5;
    background: url('https://images.unsplash.com/photo-1441986300917-64674bd600d8?q=80&w=2070&auto=format&fit=crop') center/cover;
}

/* Footer */
footer {
    padding: 6rem 0 2rem;
